    rocblas_handle handle = at::cuda::getCurrentCUDABlasHandle();

    const float alpha = 1.0f;
    const float beta = 0.0f;

    // For row-major: C = A * B
    // In col-major this is: C^T = B^T * A^T
    // rocBLAS computes C = alpha * op(A) * op(B) + beta * C in column-major
