            for (int m = 0; m < TM; m++) {
                #pragma unroll
                for (int n = 0; n < TN; n++) {
                    regC[m][n] += regA[m] * regB[n];
                }
            }
        }

        __syncthreads();
    }

    // Store results to global memory
    #pragma unroll
    for (int m = 0; m < TM; m++) {
        #pragma unroll
        for (int n = 0; n < TN; n++) {
            int globalRow = rowC + m;
            int globalCol = colC + n;
            if (globalRow < N && globalCol < N) {
                C[globalRow * N + globalCol] = regC[m][n];
            }
