    for (int m = 0; m < TM; m++) {
        #pragma unroll
        for (int n = 0; n < TN; n++) {
            int globalM = baseM + threadM + m;
            int globalN = baseN + threadN + n;
            if (globalM < N && globalN < N) {
                C[globalM * N + globalN] = regC[m][n];
            }
        }
    }
}

